def handle_request(self, request: httpx.Request) -> httpx.Response:
    scheme = request.url.scheme
    netloc = request.url.netloc.decode(encoding="ascii")
    path = request.url.path
    raw_path = request.url.raw_path
    query = request.url.query.decode(encoding="ascii")

    default_port = {"http": 80, "ws": 80, "https": 443, "wss": 443}[scheme]

    if ":" in netloc:
        host, port_string = netloc.split(":", 1)
        port = int(port_string)
    else:
        host = netloc
        port = default_port

    # Include the 'host' header.
    if "host" in request.headers:
        headers: list[tuple[bytes, bytes]] = []
    elif port == default_port:  # pragma: no cover
        headers = [(b"host", host.encode())]
    else:  # pragma: no cover
        headers = [(b"host", (f"{host}:{port}").encode())]

    # Include other request headers.
    headers += [
        (key.lower().encode(), value.encode())
        for key, value in request.headers.multi_items()
    ]

    scope: dict[str, typing.Any]

    if scheme in {"ws", "wss"}:
        subprotocol = request.headers.get("sec-websocket-protocol", None)
        if subprotocol is None:
            subprotocols: typing.Sequence[str] = []
        else:
            subprotocols = [value.strip() for value in subprotocol.split(",")]
        scope = {
            "type": "websocket",
            "path": unquote(path),
            "raw_path": raw_path,
            "root_path": self.root_path,
            "scheme": scheme,
            "query_string": query.encode(),
            "headers": headers,
            "client": None,
            "server": [host, port],
            "subprotocols": subprotocols,
            "state": self.app_state.copy(),
        }
        session = WebSocketTestSession(self.app, scope, self.portal_factory)
        raise _Upgrade(session)

    scope = {
        "type": "http",
        "http_version": "1.1",
        "method": request.method,
        "path": unquote(path),
        "raw_path": raw_path,
        "root_path": self.root_path,
        "scheme": scheme,
        "query_string": query.encode(),
        "headers": headers,
        "client": None,
        "server": [host, port],
        "extensions": {"http.response.debug": {}},
        "state": self.app_state.copy(),
    }

    request_complete = False
    response_started = False
    response_complete: anyio.Event
    raw_kwargs: dict[str, typing.Any] = {"stream": io.BytesIO()}
    template = None
    context = None

    async def receive() -> Message:
        nonlocal request_complete

        if request_complete:
            if not response_complete.is_set():
                await response_complete.wait()
            return {"type": "http.disconnect"}

        body = request.read()
        if isinstance(body, str):
            body_bytes: bytes = body.encode("utf-8")  # pragma: no cover
        elif body is None:
            body_bytes = b""  # pragma: no cover
        elif isinstance(body, GeneratorType):
            try:  # pragma: no cover
                chunk = body.send(None)
                if isinstance(chunk, str):
                    chunk = chunk.encode("utf-8")
                return {"type": "http.request", "body": chunk, "more_body": True}
            except StopIteration:  # pragma: no cover
                request_complete = True
                return {"type": "http.request", "body": b""}
        else:
            body_bytes = body

        request_complete = True
        return {"type": "http.request", "body": body_bytes}

    async def send(message: Message) -> None:
        nonlocal raw_kwargs, response_started, template, context

        if message["type"] == "http.response.start":
            assert (
                not response_started
            ), 'Received multiple "http.response.start" messages.'
            raw_kwargs["status_code"] = message["status"]
            raw_kwargs["headers"] = [
                (key.decode(), value.decode())
                for key, value in message.get("headers", [])
            ]
            response_started = True
        elif message["type"] == "http.response.body":
            assert (
                response_started
            ), 'Received "http.response.body" without "http.response.start".'
            assert (
                not response_complete.is_set()
            ), 'Received "http.response.body" after response completed.'
            body = message.get("body", b"")
            more_body = message.get("more_body", False)
            if request.method != "HEAD":
                raw_kwargs["stream"].write(body)
            if not more_body:
                raw_kwargs["stream"].seek(0)
                response_complete.set()
        elif message["type"] == "http.response.debug":
            template = message["info"]["template"]
            context = message["info"]["context"]

    try:
        with self.portal_factory() as portal:
            response_complete = portal.call(anyio.Event)
            portal.call(self.app, scope, receive, send)
    except BaseException as exc:
        if self.raise_server_exceptions:
            raise exc

    if self.raise_server_exceptions:
        assert response_started, "TestClient did not receive any response."
    elif not response_started:
        raw_kwargs = {
            "status_code": 500,
            "headers": [],
            "stream": io.BytesIO(),
        }

    raw_kwargs["stream"] = httpx.ByteStream(raw_kwargs["stream"].read())

    response = httpx.Response(**raw_kwargs, request=request)
    if template is not None:
        response.template = template  # type: ignore[attr-defined]
        response.context = context  # type: ignore[attr-defined]
    return response

def _choose_redirect_arg(
    self,
    follow_redirects: bool | None,
    allow_redirects: bool | None,
) -> bool | httpx._client.UseClientDefault:
    redirect: bool | httpx._client.UseClientDefault = (
        httpx._client.USE_CLIENT_DEFAULT
    )
    if allow_redirects is not None:
        message = (
            "The `allow_redirects` argument is deprecated. "
            "Use `follow_redirects` instead."
        )
        warnings.warn(message, DeprecationWarning)
        redirect = allow_redirects
    if follow_redirects is not None:
        redirect = follow_redirects
    elif allow_redirects is not None and follow_redirects is not None:
        raise RuntimeError(  # pragma: no cover
            "Cannot use both `allow_redirects` and `follow_redirects`."
        )
    return redirect

