def __call__(self, *args: Any, **kwargs: Any) -> str | None:
    try:
        return self.function(*args, **kwargs)
    except TypeError as te:
        print(f"{self.function.__name__.strip()!r}: {self.function.__doc__.strip()}")
        pwndbg.exception.handle(self.function.__name__)
    except Exception:
        pwndbg.exception.handle(self.function.__name__)
    return None

def fix(
    arg: gdb.Value | str, sloppy: bool = False, quiet: bool = True, reraise: bool = False
) -> str | gdb.Value | None:
    """Fix a single command-line argument coming from the GDB CLI.

    Arguments:
        arg(str): Original string representation (e.g. '0', '$rax', '$rax+44')
        sloppy(bool): If ``arg`` cannot be evaluated, return ``arg``. (default: False)
        quiet(bool): If an error occurs, suppress it. (default: True)
        reraise(bool): If an error occurs, raise the exception. (default: False)

    Returns:
        Ideally ``gdb.Value`` object.  May return a ``str`` if ``sloppy==True``.
        May return ``None`` if ``sloppy == False and reraise == False``.
    """
    if isinstance(arg, gdb.Value):
        return arg

    try:
        parsed = gdb.parse_and_eval(arg)
        return parsed
    except Exception:
        pass

    try:
        arg = pwndbg.gdblib.regs.fix(arg)
        return gdb.parse_and_eval(arg)
    except Exception as e:
        if not quiet:
            print(e)
        if reraise:
            raise e

    if sloppy:
        return arg

    return None

def get_redundant_calls(cls, node: nodes.Call) -> list[nodes.Call]:
    return [
        arg
        for arg in node.args
        if (
            cls.is_min_max_call(arg)
            and arg.func.name == node.func.name
            # Nesting is useful for finding the maximum in a matrix.
            # Allow: max(max([[1, 2, 3], [4, 5, 6]]))
            # Meaning, redunant call only if parent max call has more than 1 arg.
            and len(arg.parent.args) > 1
        )
    ]

def get_config_metrics(config):
    metrics = None
    sub_evaluation = config.get('sub_evaluation', False)
    if sub_evaluation is not None:
        size = config.get('subsample_size')
        subset_metrics = config.get('subset_metrics',[])
        for item in subset_metrics:
            subset_size = item.get('subset_size')
            if size is None or subset_size == size:
                # first subset_metrics or matching subsample_size
                metrics = item.get('metrics')
                break

    return config.get('metrics',[]) if (metrics is None) else metrics

def stop_pool(self):
    # lazy import to avoid exception if not using the backend_pool
    # and libvirt not installed (#1185)
    import libvirt

    log.msg(eventid="cowrie.backend_pool.service", format="Trying pool clean stop")

    # stop loop
    if self.loop_next_call:
        self.loop_next_call.cancel()

    # try destroying all guests
    for guest in self.guests:
        self.qemu.destroy_guest(guest["domain"], guest["snapshot"])

    # force destroy remaining stuff
    self.qemu.destroy_all_cowrie()

    # close any NAT sockets
    if not self.local_pool and self.use_nat or self.pool_only:
        log.msg(
            eventid="cowrie.backend_pool.service", format="Free all NAT bindings"
        )
        self.nat_service.free_all()

    try:
        self.qemu.stop_backend()
    except libvirt.libvirtError:
        print("Not connected to QEMU")  # noqa: T201

def _normalize(x, norm=None):
    """
    Apply one-hot encoding or z-score to a list of node features
    """
    if norm == "ohe":
        fnorm = OneHotEncoder(sparse=False, categories="auto")
    elif norm == "zscore":
        fnorm = StandardScaler()
    else:
        return x
    return fnorm.fit_transform(x)

def __init__(self, transforms=None, **kwargs):
    self.a = None  # Used for mixed-mode datasets
    # Read extra kwargs
    for k, v in kwargs.items():
        setattr(self, k, v)

    # Download data
    if not osp.exists(self.path):
        self.download()

    # Read graphs
    self.graphs = self.read()
    if self.a is None and self.__len__() > 0 and "a" not in self.graphs[0]:
        warnings.warn(
            "The graphs in this dataset have no adjacency matrix. "
            "Is this intentional?"
        )

    # Apply transforms
    if transforms is not None:
        if not isinstance(transforms, (list, tuple)) and callable(transforms):
            transforms = [transforms]
        elif not all([callable(t) for t in transforms]):
            raise ValueError(
                "`transforms` must be a callable or list of " "callables"
            )
        else:
            pass
        for t in transforms:
            self.apply(t)

