def crawl_website(self, url: str, limit: Optional[int] = None) -> str:
    """Use this function to Crawls a website using Firecrawl.

    Args:
        url (str): The URL to crawl.
        limit (int): The maximum number of pages to crawl

    Returns:
        The results of the crawling.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore

    params["poll_interval"] = self.poll_interval

    crawl_result = self.app.crawl_url(url, **params)
    return json.dumps(crawl_result.model_dump(), cls=CustomJSONEncoder)

def search(self, query: str, limit: Optional[int] = None):
    """Use this function to search for the web using Firecrawl.

    Args:
        query (str): The query to search for.
        limit (int): The maximum number of results to return.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore
    if self.search_params:
        params.update(self.search_params)

    search_result = self.app.search(query, **params)
    if search_result.success:
        return json.dumps(search_result.data, cls=CustomJSONEncoder)
    else:
        return "Error searching with the Firecrawl tool: " + search_result.error

def get_function_call(
    name: str,
    arguments: Optional[str] = None,
    call_id: Optional[str] = None,
    functions: Optional[Dict[str, Function]] = None,
) -> Optional[FunctionCall]:
    if functions is None:
        return None

    function_to_call: Optional[Function] = None
    if name in functions:
        function_to_call = functions[name]
    if function_to_call is None:
        log_error(f"Function {name} not found")
        return None

    function_call = FunctionCall(function=function_to_call)
    if call_id is not None:
        function_call.call_id = call_id
    if arguments is not None and arguments != "":
        try:
            try:
                _arguments = json.loads(arguments)
            except Exception as e:
                import ast
                _arguments = ast.literal_eval(arguments)
        except Exception as e:
            log_error(f"Unable to decode function arguments:\n{arguments}\nError: {e}")
            function_call.error = (
                f"Error while decoding function arguments: {e}\n\n"
                f"Please make sure we can json.loads() the arguments and retry."
            )
            return function_call

        if not isinstance(_arguments, dict):
            log_error(f"Function arguments are not a valid JSON object: {arguments}")
            function_call.error = "Function arguments are not a valid JSON object.\n\n Please fix and retry."
            return function_call

        try:
            clean_arguments: Dict[str, Any] = {}
            for k, v in _arguments.items():
                if isinstance(v, str):
                    _v = v.strip().lower()
                    if _v in ("none", "null"):
                        clean_arguments[k] = None
                    elif _v == "true":
                        clean_arguments[k] = True
                    elif _v == "false":
                        clean_arguments[k] = False
                    else:
                        clean_arguments[k] = v.strip()
                else:
                    clean_arguments[k] = v

            function_call.arguments = clean_arguments
        except Exception as e:
            log_error(f"Unable to parsing function arguments:\n{arguments}\nError: {e}")
            function_call.error = f"Error while parsing function arguments: {e}\n\n Please fix and retry."
            return function_call
    return function_call

def send_completion(self, messages, functions, stream, temperature=None):
    if os.environ.get("AIDER_SANITY_CHECK_TURNS"):
        sanity_check_messages(messages)

    if self.is_deepseek_r1():
        messages = ensure_alternating_roles(messages)

    kwargs = dict(
        model=self.name,
        stream=stream,
    )

    if self.use_temperature is not False:
        if temperature is None:
            if isinstance(self.use_temperature, bool):
                temperature = 0
            else:
                temperature = float(self.use_temperature)

        kwargs["temperature"] = temperature

    if functions is not None:
        function = functions[0]
        kwargs["tools"] = [dict(type="function", function=function)]
        kwargs["tool_choice"] = {"type": "function", "function": {"name": function["name"]}}
    if self.extra_params:
        kwargs.update(self.extra_params)
    if self.is_ollama() and "num_ctx" not in kwargs:
        num_ctx = int(self.token_count(messages) * 1.25) + 8192
        kwargs["num_ctx"] = num_ctx
    key = json.dumps(kwargs, sort_keys=True).encode()

    # dump(kwargs)

    hash_object = hashlib.sha1(key)
    if "timeout" not in kwargs:
        kwargs["timeout"] = request_timeout
    if self.verbose:
        dump(kwargs)
    kwargs["messages"] = messages

    # Are we using github copilot?
    if "GITHUB_COPILOT_TOKEN" in os.environ:
        if "extra_headers" not in kwargs:
            kwargs["extra_headers"] = {
                "Editor-Version": f"aider/{__version__}",
                "Copilot-Integration-Id": "vscode-chat",
            }

        self.github_copilot_token_to_open_ai_key(kwargs["extra_headers"])

    res = litellm.completion(tools=[{"googleSearch": {}}], **kwargs)
    return hash_object, res

def with_history_disabled(func):
    """Decorator to temporarily disable history saving for the prompt session buffer."""

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            orig_buf_append = self.prompt_session.default_buffer.append_to_history
            self.prompt_session.default_buffer.append_to_history = (
                lambda: None
            )  # Replace with no-op
        except AttributeError:
            pass

        try:
            return func(self, *args, **kwargs)
        except Exception:
            raise
        finally:
            if orig_buf_append:
                self.prompt_session.default_buffer.append_to_history = orig_buf_append

    return wrapper

def cmd_lint(self, args="", fnames=None):
    "Lint and fix in-chat files or all dirty files if none in chat"

    if not self.coder.repo:
        self.io.tool_error("No git repository found.")
        return

    if not fnames:
        fnames = self.coder.get_inchat_relative_files()

    # If still no files, get all dirty files in the repo
    if not fnames and self.coder.repo:
        fnames = self.coder.repo.get_dirty_files()

    if not fnames:
        self.io.tool_warning("No dirty files to lint.")
        return

    fnames = [self.coder.abs_root_path(fname) for fname in fnames]

    lint_coder = None
    for fname in fnames:
        try:
            errors = self.coder.linter.lint(fname)
        except FileNotFoundError as err:
            self.io.tool_error(f"Unable to lint {fname}")
            self.io.tool_output(str(err))
            continue

        if not errors:
            continue

        self.io.tool_output(errors)
        if not self.io.confirm_ask(f"Fix lint errors in {fname}?", default="y"):
            continue

        # Commit everything before we start fixing lint errors
        if self.coder.repo.is_dirty() and self.coder.dirty_commits:
            self.cmd_commit("")

        if not lint_coder:
            lint_coder = self.coder.clone(
                # Clear the chat history, fnames
                cur_messages=[],
                done_messages=[],
                fnames=None,
            )

        lint_coder.add_rel_fname(fname)
        lint_coder.run(errors)
        lint_coder.abs_fnames = set()

    if lint_coder and self.coder.repo.is_dirty() and self.coder.auto_commits:
        self.cmd_commit("")

def cmd_add(self, args):
    "Add files to the chat so aider can edit them or review them in detail"

    all_matched_files = set()

    filenames = parse_quoted_filenames(args)
    for word in filenames:
        if Path(word).is_absolute():
            fname = Path(word)
        else:
            fname = Path(self.coder.root) / word

        if self.coder.repo and self.coder.repo.ignored_file(fname):
            self.io.tool_warning(f"Skipping {fname} due to aiderignore or --subtree-only.")
            continue

        if fname.exists():
            if fname.is_file():
                all_matched_files.add(str(fname))
                continue
            # an existing dir, escape any special chars so they won't be globs
            word = re.sub(r"([\*\?\[\]])", r"[\1]", word)

        matched_files = self.glob_filtered_to_repo(word)
        if matched_files:
            all_matched_files.update(matched_files)
            continue

        if "*" in str(fname) or "?" in str(fname):
            self.io.tool_error(
                f"No match, and cannot create file with wildcard characters: {fname}"
            )
            continue

        if fname.exists() and fname.is_dir() and self.coder.repo:
            self.io.tool_error(f"Directory {fname} is not in git.")
            self.io.tool_output(f"You can add to git with: /git add {fname}")
            continue

        if self.io.confirm_ask(f"No files matched '{word}'. Do you want to create {fname}?"):
            try:
                fname.parent.mkdir(parents=True, exist_ok=True)
                fname.touch()
                all_matched_files.add(str(fname))
            except OSError as e:
                self.io.tool_error(f"Error creating file {fname}: {e}")

    for matched_file in sorted(all_matched_files):
        abs_file_path = self.coder.abs_root_path(matched_file)

        if not abs_file_path.startswith(self.coder.root) and not is_image_file(matched_file):
            self.io.tool_error(
                f"Can not add {abs_file_path}, which is not within {self.coder.root}"
            )
            continue

        if self.coder.repo and self.coder.repo.git_ignored_file(matched_file):
            self.io.tool_error(f"Can't add {matched_file} which is in gitignore")
            continue

        if abs_file_path in self.coder.abs_fnames:
            self.io.tool_error(f"{matched_file} is already in the chat as an editable file")
            continue
        elif abs_file_path in self.coder.abs_read_only_fnames:
            if self.coder.repo and self.coder.repo.path_in_repo(matched_file):
                self.coder.abs_read_only_fnames.remove(abs_file_path)
                self.coder.abs_fnames.add(abs_file_path)
                self.io.tool_output(
                    f"Moved {matched_file} from read-only to editable files in the chat"
                )
            else:
                self.io.tool_error(
                    f"Cannot add {matched_file} as it's not part of the repository"
                )
        else:
            if is_image_file(matched_file) and not self.coder.main_model.info.get(
                "supports_vision"
            ):
                self.io.tool_error(
                    f"Cannot add image file {matched_file} as the"
                    f" {self.coder.main_model.name} does not support images."
                )
                continue
            content = self.io.read_text(abs_file_path)
            if content is None:
                self.io.tool_error(f"Unable to read {matched_file}")
            else:
                self.coder.abs_fnames.add(abs_file_path)
                fname = self.coder.get_rel_fname(abs_file_path)
                self.io.tool_output(f"Added {fname} to the chat")
                self.coder.check_added_files()

def cmd_run(self, args, add_on_nonzero_exit=False):
    "Run a shell command and optionally add the output to the chat (alias: !)"
    exit_status, combined_output = run_cmd(
        args, verbose=self.verbose, error_print=self.io.tool_error, cwd=self.coder.root
    )

    if combined_output is None:
        return

    # Calculate token count of output
    token_count = self.coder.main_model.token_count(combined_output)
    k_tokens = token_count / 1000

    if add_on_nonzero_exit:
        add = exit_status != 0
    else:
        add = self.io.confirm_ask(f"Add {k_tokens:.1f}k tokens of command output to the chat?")

    if add:
        num_lines = len(combined_output.strip().splitlines())
        line_plural = "line" if num_lines == 1 else "lines"
        self.io.tool_output(f"Added {num_lines} {line_plural} of output to the chat.")

        msg = prompts.run_output.format(
            command=args,
            output=combined_output,
        )

        self.coder.cur_messages += [
            dict(role="user", content=msg),
            dict(role="assistant", content="Ok."),
        ]

        if add_on_nonzero_exit and exit_status != 0:
            # Return the formatted output message for test failures
            return msg
        elif add and exit_status != 0:
            self.io.placeholder = "What's wrong? Fix"

    # Return None if output wasn't added or command succeeded
    return None

