            .message-small {{
                font-weight: 400;
                font-size: 14px;
                line-height: 150%;
                letter-spacing: -0.02em;
                text-align: center;
                vertical-align: middle;
                color: {text_color_small};
            }}
            .loader {{
                width: 12px;
