def format_messages(messages: List[Message]) -> Tuple[List[Dict[str, str]], str]:
    """
    Process the list of messages and separate them into API messages and system messages.

    Args:
        messages (List[Message]): The list of messages to process.

    Returns:
        Tuple[List[Dict[str, str]], str]: A tuple containing the list of API messages and the concatenated system messages.
    """
    chat_messages: List[Dict[str, str]] = []
    system_messages: List[str] = []

    for message in messages:
        content = message.content or ""
        if message.role == "system":
            if content is not None:
                system_messages.append(content)  # type: ignore
            continue
        elif message.role == "user":
            if isinstance(content, str):
                content = [{"type": "text", "text": content}]

            if message.images is not None:
                for image in message.images:
                    image_content = _format_image_for_message(image)
                    if image_content:
                        content.append(image_content)

            if message.files is not None:
                for file in message.files:
                    file_content = _format_file_for_message(file)
                    if file_content:
                        content.append(file_content)

            if message.audio is not None and len(message.audio) > 0:
                log_warning("Audio input is currently unsupported.")

            if message.videos is not None and len(message.videos) > 0:
                log_warning("Video input is currently unsupported.")

        elif message.role == "assistant":
            content = []

            if message.thinking is not None and message.provider_data is not None:
                from anthropic.types import RedactedThinkingBlock, ThinkingBlock

                content.append(
                    ThinkingBlock(
                        thinking=message.thinking,
                        signature=message.provider_data.get("signature"),
                        type="thinking",
                    )
                )

            if message.redacted_thinking is not None:
                from anthropic.types import RedactedThinkingBlock

                content.append(RedactedThinkingBlock(data=message.redacted_thinking, type="redacted_thinking"))

            if isinstance(message.content, str) and message.content:
                if message.content != " ":
                    content.append(TextBlock(text=message.content, type="text"))

            if message.tool_calls:
                for tool_call in message.tool_calls:
                    content.append(
                        ToolUseBlock(
                            id=tool_call["id"],
                            input=json.loads(tool_call["function"]["arguments"])
                            if "arguments" in tool_call["function"]
                            else {},
                            name=tool_call["function"]["name"],
                            type="tool_use",
                        )
                    )

        chat_messages.append({"role": ROLE_MAP[message.role], "content": content})  # type: ignore
    return chat_messages, " ".join(system_messages)

def read(self, path: Union[Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(path, Path):
            if not path.exists():
                raise FileNotFoundError(f"Could not find file: {path}")
            log_info(f"Reading: {path}")
            json_name = path.name.split(".")[0]
            json_contents = json.loads(path.read_text("utf-8"))

        elif isinstance(path, BytesIO):
            log_info(f"Reading uploaded file: {path.name}")
            json_name = path.name.split(".")[0]
            path.seek(0)
            json_contents = json.load(path)

        else:
            raise ValueError("Unsupported file type. Must be Path or BytesIO.")

        if isinstance(json_contents, dict):
            json_contents = [json_contents]

        documents = [
            Document(
                name=json_name,
                id=str(uuid4()),
                meta_data={"page": page_number},
                content=json.dumps(content),
            )
            for page_number, content in enumerate(json_contents, start=1)
        ]
        if self.chunk:
            chunked_documents = []
            for document in documents:
                chunked_documents.extend(self.chunk_document(document))
            return chunked_documents
        return documents
    except Exception:
        raise

def read(self, pdf: Union[str, Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(pdf, str):
            doc_name = pdf.split("/")[-1].split(".")[0].replace(" ", "_")
        else:
            doc_name = pdf.name.split(".")[0]
    except Exception:
        doc_name = "pdf"

    log_info(f"Reading: {doc_name}")

    try:
        doc_reader = DocumentReader(pdf)
    except PdfStreamError as e:
        logger.error(f"Error reading PDF: {e}")
        return []

    documents = []
    for page_number, page in enumerate(doc_reader.pages, start=1):
        documents.append(
            Document(
                name=doc_name,
                id=str(uuid4()),
                meta_data={"page": page_number},
                content=page.extract_text(),
            )
        )
    if self.chunk:
        return self._build_chunked_documents(documents)
    return documents

def read(self, file: Union[Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(file, Path):
            if not file.exists():
                raise FileNotFoundError(f"Could not find file: {file}")
            log_info(f"Reading: {file}")
            file_name = file.stem
            file_contents = file.read_text("utf-8")
        else:
            log_info(f"Reading uploaded file: {file.name}")
            file_name = file.name.split(".")[0]
            file.seek(0)
            file_contents = file.read().decode("utf-8")

        documents = [
            Document(
                name=file_name,
                id=str({uuid.uuid4()}),
                content=file_contents,
            )
        ]
        if self.chunk:
            chunked_documents = []
            for document in documents:
                chunked_documents.extend(self.chunk_document(document))
            return chunked_documents
        return documents
    except Exception as e:
        logger.error(f"Error reading: {file}: {e}")
        return []

async def async_read(self, file: Union[Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(file, Path):
            if not file.exists():
                raise FileNotFoundError(f"Could not find file: {file}")

            log_info(f"Reading asynchronously: {file}")
            file_name = file.stem

            try:
                import aiofiles

                async with aiofiles.open(file, "r", encoding="utf-8") as f:
                    file_contents = await f.read()
            except ImportError:
                logger.warning("aiofiles not installed, using synchronous file I/O")
                file_contents = file.read_text("utf-8")
        else:
            log_info(f"Reading uploaded file asynchronously: {file.name}")
            file_name = file.name.split(".")[0]
            file.seek(0)
            file_contents = file.read().decode("utf-8")

        document = Document(
            name=file_name,
            id=str({uuid.uuid4()}),
            content=file_contents,
        )

        if self.chunk:
            return await self._async_chunk_document(document)
        return [document]
    except Exception as e:
        logger.error(f"Error reading asynchronously: {file}: {e}")
        return []

