def _get_response_format(self, model: Optional[Model] = None) -> Optional[Union[Dict, Type[BaseModel]]]:
    self.model = cast(Model, model or self.model)
    if self.response_model is None:
        return None
    else:
        json_response_format = {"type": "json_object"}

        if self.model.supports_native_structured_outputs:
            if not self.use_json_mode or self.structured_outputs:
                log_debug("Setting Model.response_format to Agent.response_model")
                return self.response_model
            else:
                log_debug(
                    "Model supports native structured outputs but it is not enabled. Using JSON mode instead."
                )
                return json_response_format

        elif self.model.supports_json_schema_outputs:
            if self.use_json_mode or (not self.structured_outputs):
                log_debug("Setting Model.response_format to JSON response mode")
                return {
                    "type": "json_schema",
                    "json_schema": {
                        "name": self.response_model.__name__,
                        "schema": self.response_model.model_json_schema(),
                    },
                }
            else:
                return None

        else:
            log_debug("Model does not support structured or JSON schema outputs.")
            return json_response_format

def get_recent_sessions(
    self,
    user_id: Optional[str] = None,
    entity_id: Optional[str] = None,
    limit: Optional[int] = 2,
) -> List[Session]:
    """Get the last N sessions, ordered by created_at descending.

    Args:
        num_history_sessions: Number of most recent sessions to return
        user_id: Filter by user ID
        entity_id: Filter by entity ID (agent_id, team_id, or workflow_id)

    Returns:
        List[Session]: List of most recent sessions
    """
    sessions: List[Session] = []
    try:
        with self.SqlSession.begin() as sess:
            # Build base query
            stmt = select(self.table)

            # Add filters
            if user_id is not None:
                stmt = stmt.where(self.table.c.user_id == user_id)
            if entity_id is not None:
                if self.mode == "agent":
                    stmt = stmt.where(self.table.c.agent_id == entity_id)
                elif self.mode == "team":
                    stmt = stmt.where(self.table.c.team_id == entity_id)
                elif self.mode == "workflow":
                    stmt = stmt.where(self.table.c.workflow_id == entity_id)

            # Order by created_at desc and limit results
            stmt = stmt.order_by(self.table.c.created_at.desc())
            if limit is not None:
                stmt = stmt.limit(limit)

            # Execute query
            rows = sess.execute(stmt).fetchall()
            for row in rows:
                if row.session_id is not None:
                    if self.mode == "agent":
                        session = AgentSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "team":
                        session = TeamSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "workflow":
                        session = WorkflowSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)

    except Exception as e:
        if "doesn't exist" in str(e):
            log_debug(f"Table does not exist: {self.table.name}")
            self.create()
        else:
            logger.error(f"Error getting last {num_history_sessions} sessions: {e}")

    return sessions

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

def get_recent_sessions(
    self,
    user_id: Optional[str] = None,
    entity_id: Optional[str] = None,
    limit: Optional[int] = 2,
) -> List[Session]:
    """Get the last N sessions, ordered by created_at descending.

    Args:
        num_history_sessions: Number of most recent sessions to return
        user_id: Filter by user ID
        entity_id: Filter by entity ID (agent_id, team_id, or workflow_id)

    Returns:
        List[Session]: List of most recent sessions
    """
    sessions: List[Session] = []
    try:
        with self.SqlSession.begin() as sess:
            # Build base query
            stmt = select(self.table)

            # Add filters
            if user_id is not None:
                stmt = stmt.where(self.table.c.user_id == user_id)
            if entity_id is not None:
                if self.mode == "agent":
                    stmt = stmt.where(self.table.c.agent_id == entity_id)
                elif self.mode == "team":
                    stmt = stmt.where(self.table.c.team_id == entity_id)
                elif self.mode == "workflow":
                    stmt = stmt.where(self.table.c.workflow_id == entity_id)

            # Order by created_at desc and limit results
            stmt = stmt.order_by(self.table.c.created_at.desc())
            if limit is not None:
                stmt = stmt.limit(limit)

            # Execute query
            rows = sess.execute(stmt).fetchall()
            for row in rows:
                if row.session_id is not None:
                    if self.mode == "agent":
                        session = AgentSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "team":
                        session = TeamSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "workflow":
                        session = WorkflowSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)

    except Exception as e:
        if "doesn't exist" in str(e):
            log_debug(f"Table does not exist: {self.table.name}")
            self.create()
        else:
            logger.error(f"Error getting last {num_history_sessions} sessions: {e}")

    return sessions

def get_recent_sessions(
    self,
    user_id: Optional[str] = None,
    entity_id: Optional[str] = None,
    limit: Optional[int] = 2,
) -> List[Session]:
    """Get the last N sessions, ordered by created_at descending.

    Args:
        num_history_sessions: Number of most recent sessions to return
        user_id: Filter by user ID
        entity_id: Filter by entity ID (agent_id, team_id, or workflow_id)

    Returns:
        List[Session]: List of most recent sessions
    """
    sessions: List[Session] = []
    # List of (created_at, data) tuples for sorting
    session_data: List[tuple[int, dict]] = []

    # First pass: collect and filter sessions
    for file in self.dir_path.glob("*.yaml"):
        try:
            with open(file, "r", encoding="utf-8") as f:
                data = self.deserialize(f.read())

                if user_id and data["user_id"] != user_id:
                    continue

                if entity_id:
                    if self.mode == "agent" and data["agent_id"] != entity_id:
                        continue
                    elif self.mode == "team" and data["team_id"] != entity_id:
                        continue
                    elif self.mode == "workflow" and data["workflow_id"] != entity_id:
                        continue

                # Store with created_at for sorting
                created_at = data.get("created_at", 0)
                session_data.append((created_at, data))

        except Exception as e:
            logger.error(f"Error reading session file {file}: {e}")
            continue

    # Sort by created_at descending and take only num_history_sessions
    session_data.sort(key=lambda x: x[0], reverse=True)
    if limit is not None:
        session_data = session_data[:limit]

    # Convert filtered and sorted data to Session objects
    for _, data in session_data:
        session: Optional[Session] = None
        if self.mode == "agent":
            session = AgentSession.from_dict(data)
        elif self.mode == "team":
            session = TeamSession.from_dict(data)
        elif self.mode == "workflow":
            session = WorkflowSession.from_dict(data)

        if session is not None:
            sessions.append(session)

    return sessions

def store_result_in_file(
    file_path: str,
    result: Union["AccuracyResult", "PerformanceResult", "ReliabilityResult"],
    eval_id: Optional[str] = None,
    name: Optional[str] = None,
):
    """Store the given result in the given file path"""
    try:
        import json

        fn_path = Path(file_path.format(name=name, eval_id=eval_id))
        if not fn_path.parent.exists():
            fn_path.parent.mkdir(parents=True, exist_ok=True)
        fn_path.write_text(json.dumps(asdict(result), indent=4))
    except Exception as e:
        logger.warning(f"Failed to save result to file: {e}")

def load(
    self,
    recreate: bool = False,
    upsert: bool = True,
    skip_existing: bool = True,
    filters: Optional[Dict[str, Any]] = None,
) -> None:
    """Load the website contents to the vector db"""

    if self.vector_db is None:
        logger.warning("No vector db provided")
        return

    if self.reader is None:
        logger.warning("No reader provided")
        return

    if recreate:
        log_debug("Dropping collection")
        self.vector_db.drop()

    log_debug("Creating collection")
    self.vector_db.create()

    log_info("Loading knowledge base")

    # Given that the crawler needs to parse the URL before existence can be checked
    # We check if the website url exists in the vector db if recreate is False
    urls_to_read = self.urls.copy()
    if not recreate:
        for url in urls_to_read:
            log_debug(f"Checking if {url} exists in the vector db")
            if self.vector_db.name_exists(name=url):
                log_debug(f"Skipping {url} as it exists in the vector db")
                urls_to_read.remove(url)

    num_documents = 0
    for url in urls_to_read:
        if document_list := self.reader.read(url=url):
            # Filter out documents which already exist in the vector db
            if not recreate:
                document_list = [document for document in document_list if not self.vector_db.doc_exists(document)]
                if not document_list:
                    continue
            if upsert and self.vector_db.upsert_available():
                self.vector_db.upsert(documents=document_list, filters=filters)
            else:
                self.vector_db.insert(documents=document_list, filters=filters)
            num_documents += len(document_list)
            log_info(f"Loaded {num_documents} documents to knowledge base")

    if self.optimize_on is not None and num_documents > self.optimize_on:
        log_debug("Optimizing Vector DB")
        self.vector_db.optimize()

def _create_run_data(self) -> Dict[str, Any]:
    """Create and return the run data dictionary."""
    run_response_format = "text"
    if self.response_model is not None:
        run_response_format = "json"
    elif self.markdown:
        run_response_format = "markdown"

    functions = {}
    if self._functions_for_model:
        functions = {
            f_name: func.to_dict()
            for f_name, func in self._functions_for_model.items()
            if isinstance(func, Function)
        }

    run_data: Dict[str, Any] = {
        "functions": functions,
        "metrics": self.run_response.metrics,  # type: ignore
    }

    if self.monitoring:
        run_data.update(
            {
                "run_input": self.run_input,
                "run_response": self.run_response.to_dict(),  # type: ignore
                "run_response_format": run_response_format,
            }
        )

    return run_data

def from_callable(cls, c: Callable, strict: bool = False) -> "Function":
    from inspect import getdoc, signature

    from agno.utils.json_schema import get_json_schema

    function_name = c.__name__
    parameters = {"type": "object", "properties": {}, "required": []}
    try:
        sig = signature(c)
        type_hints = get_type_hints(c)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {function_name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions: Dict[str, Any] = {}
        if docstring := getdoc(c):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name
                    if param_type is None:
                        param_descriptions[param_name] = param.description
                    else:
                        param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value (this would include optional fields)
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        # log_debug(f"JSON schema for {function_name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {function_name}: {e}", exc_info=True)

    entrypoint = cls._wrap_callable(c)

    return cls(
        name=function_name,
        description=get_entrypoint_docstring(entrypoint=c),
        parameters=parameters,
        entrypoint=entrypoint,
    )

def process_entrypoint(self, strict: bool = False):
    """Process the entrypoint and make it ready for use by an agent."""
    from inspect import getdoc, signature

    from agno.utils.json_schema import get_json_schema

    if self.skip_entrypoint_processing:
        if strict:
            self.process_schema_for_strict()
        return

    if self.entrypoint is None:
        return

    parameters = {"type": "object", "properties": {}, "required": []}

    params_set_by_user = False
    # If the user set the parameters (i.e. they are different from the default), we should keep them
    if self.parameters != parameters:
        params_set_by_user = True

    if self.requires_user_input:
        self.user_input_schema = self.user_input_schema or []

    try:
        sig = signature(self.entrypoint)
        type_hints = get_type_hints(self.entrypoint)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {self.name}: {type_hints}")

        # Filter out return type and only process parameters
        excluded_params = ["return", "agent", "team"]
        if self.requires_user_input and self.user_input_fields:
            if len(self.user_input_fields) == 0:
                excluded_params.extend(list(type_hints.keys()))
            else:
                excluded_params.extend(self.user_input_fields)

        # Get filtered list of parameter types
        param_type_hints = {name: type_hints.get(name) for name in sig.parameters if name not in excluded_params}

        # Parse docstring for parameters
        param_descriptions = {}
        param_descriptions_clean = {}
        if docstring := getdoc(self.entrypoint):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name

                    # TODO: We should use type hints first, then map param types in docs to json schema types.
                    # This is temporary to not lose information
                    param_descriptions[param_name] = f"({param_type}) {param.description}"
                    param_descriptions_clean[param_name] = param.description

        # If the function requires user input, we should set the user_input_schema to all parameters. The arguments provided by the model are filled in later.
        if self.requires_user_input:
            self.user_input_schema = [
                UserInputField(
                    name=name,
                    description=param_descriptions_clean.get(name),
                    field_type=type_hints.get(name, str),
                )
                for name in sig.parameters
            ]

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in excluded_params]
        else:
            # Mark a field as required if it has no default value
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in excluded_params
            ]

        if params_set_by_user:
            self.parameters["additionalProperties"] = False
            if strict:
                self.parameters["required"] = [
                    name for name in self.parameters["properties"] if name not in excluded_params
                ]
            else:
                # Mark a field as required if it has no default value
                self.parameters["required"] = [
                    name
                    for name, param in sig.parameters.items()
                    if param.default == param.empty and name != "self" and name not in excluded_params
                ]

        self.description = self.description or get_entrypoint_docstring(self.entrypoint)

        # log_debug(f"JSON schema for {self.name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {self.name}: {e}", exc_info=True)

    if not params_set_by_user:
        self.parameters = parameters

    try:
        self.entrypoint = self._wrap_callable(self.entrypoint)
    except Exception as e:
        log_warning(f"Failed to add validate decorator to entrypoint: {e}")

def get_media(media_id: str) -> dict:
    """
    Sends a GET request to the Facebook Graph API to retrieve media information.

    Args:
        media_id (str): The ID of the media to retrieve.
    """
    url = f"https://graph.facebook.com/v22.0/{media_id}"

    access_token = get_access_token()

    headers = {"Authorization": f"Bearer {access_token}"}
    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx and 5xx)
        data = response.json()

        media_url = data.get("url")
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}

    try:
        response = requests.get(media_url, headers=headers)
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx and 5xx)
        data = response.content
        return data
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}

