def build_uniforms_header(skip_generation: bool = False) -> str:
    dest = 'kitty/uniforms_generated.h'
    if skip_generation:
        return dest
    lines = []
    a = lines.append
    uniform_names: Dict[str, Tuple[str, ...]] = {}
    class_names = {}
    function_names = {}

    def find_uniform_names(raw: str) -> Iterator[str]:
        for m in re.finditer(r'^uniform\s+\S+\s+(.+?);', raw, flags=re.MULTILINE):
            for x in m.group(1).split(','):
                yield x.strip().partition('[')[0]

    for x in sorted(glob.glob('kitty/*.glsl')):
        name = os.path.basename(x).partition('.')[0]
        name, sep, shader_type = name.partition('_')
        if not sep or shader_type not in ('fragment', 'vertex'):
            continue
        class_names[name] = f'{name.capitalize()}Uniforms'
        function_names[name] = f'get_uniform_locations_{name}'
        with open(x) as f:
            raw = f.read()
        uniform_names[name] = uniform_names.setdefault(name, ()) + tuple(find_uniform_names(raw))
    for name in sorted(class_names):
        class_name, function_name, uniforms = class_names[name], function_names[name], uniform_names[name]
        a(f'typedef struct {class_name} ''{')
        for n in uniforms:
            a(f'    int {n};')
        a('}'f' {class_name};')
        a('')
        a(f'static inline void\n{function_name}(int program, {class_name} *ans) ''{')
        for n in uniforms:
            a(f'    ans->{n} = get_uniform_location(program, "{n}");')
        a('}')
        a('')
    src = '\n'.join(lines)
    try:
        with open(dest) as f:
            current = f.read()
    except FileNotFoundError:
        current = ''
    if src != current:
        with open(dest, 'w') as f:
            f.write(src)
    return dest

def make_reflective_dataset(self, candidate, eval_batch, components_to_update):
    from dspy.teleprompt.bootstrap_trace import FailedPrediction
    program = self.build_program(candidate)

    ret_d: dict[str, list[dict[str, Any]]] = {}
    for pred_name in components_to_update:
        module = None
        for name, m in program.named_predictors():
            if name == pred_name:
                module = m
                break
        assert module is not None

        items: list[dict[str, Any]] = []
        for data in eval_batch.trajectories or []:
            trace = data["trace"]
            example = data["example"]
            prediction = data["prediction"]
            module_score = data["score"]
            if hasattr(module_score, "score"):
                module_score = module_score["score"]

            trace_instances = [t for t in trace if t[0].signature.equals(module.signature)]
            if not self.add_format_failure_as_feedback:
                trace_instances = [t for t in trace_instances if not isinstance(t[2], FailedPrediction)]
            if len(trace_instances) == 0:
                continue

            selected = None
            for t in trace_instances:
                if isinstance(t[2], FailedPrediction):
                    selected = t
                    break

            if selected is None:
                if isinstance(prediction, FailedPrediction):
                    continue
                selected = self.rng.choice(trace_instances)

            inputs = selected[1]
            outputs = selected[2]

            new_inputs = {}
            new_outputs = {}

            contains_history = False
            history_key_name = None
            for input_key, input_val in inputs.items():
                if isinstance(input_val, History):
                    contains_history = True
                    assert history_key_name is None
                    history_key_name = input_key

            if contains_history:
                s = "```json\n"
                for i, message in enumerate(inputs[history_key_name].messages):
                    s += f"  {i}: {message}\n"
                s += "```"
                new_inputs["Context"] = s

            for input_key, input_val in inputs.items():
                if contains_history and input_key == history_key_name:
                    continue
                new_inputs[input_key] = str(input_val)

            if isinstance(outputs, FailedPrediction):
                s = "Couldn't parse the output as per the expected output format. The model's raw response was:\n"
                s += "```\n"
                s += outputs.completion_text + "\n"
                s += "```\n\n"
                new_outputs = s
            else:
                for output_key, output_val in outputs.items():
                    new_outputs[output_key] = str(output_val)

            d = {"Inputs": new_inputs, "Generated Outputs": new_outputs}
            if isinstance(outputs, FailedPrediction):
                adapter = ChatAdapter()
                structure_instruction = ""
                for dd in adapter.format(module.signature, [], {}):
                    structure_instruction += dd["role"] + ": " + dd["content"] + "\n"
                d["Feedback"] = "Your output failed to parse. Follow this structure:\n" + structure_instruction
                # d['score'] = self.failure_score
            else:
                feedback_fn = self.feedback_map[pred_name]
                fb = feedback_fn(
                    predictor_output=outputs,
                    predictor_inputs=inputs,
                    module_inputs=example,
                    module_outputs=prediction,
                    captured_trace=trace,
                )
                d["Feedback"] = fb["feedback"]
                if self.keep_module_scores:
                    d['score'] = module_score
                else:
                    d['score'] = fb['score']

            items.append(d)

        if len(items) == 0:
            # raise Exception(f"No valid predictions found for module {module.signature}.")
            continue
        ret_d[pred_name] = items

    if len(ret_d) == 0:
        raise Exception("No valid predictions found for any module.")

    return ret_d

