def _fixvalue(self, value):
    # type: (Any) -> int
    if not value:
        return 0
    if isinstance(value, str):
        value = value.split('+') if self.multi else list(value)
    if isinstance(value, list):
        y = 0
        for i in value:
            y |= 1 << self.names.index(i)
        value = y
    return int(value)

