class CustomJSONEncoder(json.JSONEncoder):
    """Custom JSON encoder that handles non-serializable types by converting them to strings."""

def crawl_website(self, url: str, limit: Optional[int] = None) -> str:
    """Use this function to Crawls a website using Firecrawl.

    Args:
        url (str): The URL to crawl.
        limit (int): The maximum number of pages to crawl

    Returns:
        The results of the crawling.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore

    params["poll_interval"] = self.poll_interval

    crawl_result = self.app.crawl_url(url, **params)
    return json.dumps(crawl_result.model_dump(), cls=CustomJSONEncoder)

def search(self, query: str, limit: Optional[int] = None):
    """Use this function to search for the web using Firecrawl.

    Args:
        query (str): The query to search for.
        limit (int): The maximum number of results to return.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore
    if self.search_params:
        params.update(self.search_params)

    search_result = self.app.search(query, **params)
    if search_result.success:
        return json.dumps(search_result.data, cls=CustomJSONEncoder)
    else:
        return "Error searching with the Firecrawl tool: " + search_result.error

def match_case_insensitive_module_name(mod_name: str) -> Optional[str]:
    """Check the importable datasource modules for a case-insensitive match."""

    # nocloud-net is the only datasource that requires matching on a name that
    # does not match its python module - canonicalize it here
    if "nocloud-net" == mod_name.lower():
        mod_name = mod_name[:-4]
    if not mod_name.startswith("DataSource"):
        mod_name = f"DataSource{mod_name}"
    modules = {}
    spec = importlib.util.find_spec("cloudinit.sources")
    if spec and spec.submodule_search_locations:
        for dir in spec.submodule_search_locations:
            modules.update(util.get_modules_from_dir(dir))
        for module in modules.values():
            if module.lower() == mod_name.lower():
                return module
    return mod_name

def apply_locale(self, locale, out_fn=None, keyname="LANG"):
    try:
        subp.subp(
            [
                "/usr/bin/raspi-config",
                "nonint",
                "do_change_locale",
                f"{locale}",
            ]
        )
    except subp.ProcessExecutionError:
        if not locale.endswith(".UTF-8"):
            LOG.info("Trying to set locale %s.UTF-8", locale)
            subp.subp(
