def is_enabled(self, plugin_name=None):
    """Return true if plugin is enabled."""
    if not plugin_name:
        plugin_name = self.plugin_name
    try:
        d = getattr(self.args, 'disable_' + plugin_name)
    except AttributeError:
        d = getattr(self.args, 'enable_' + plugin_name, True)
    return d is False

def main_try():
    # We wrap everything in try/except so that we can exit GDB with an error code
    # This is used by tests to check if gdbinit.py failed
    try:
        main()
    except Exception:
        print(traceback.format_exc(), file=sys.stderr, flush=True)
        os._exit(1)

def test_slot_behaviour(self, business_opening_hours):
    inst = business_opening_hours
    for attr in inst.__slots__:
        assert getattr(inst, attr, "err") != "err", f"got extra slot '{attr}'"
    assert len(mro_slots(inst)) == len(set(mro_slots(inst))), "duplicate slot"

