def test_get_optional_params(self):
    config = VolcEngineConfig()
    supported_params = config.get_supported_openai_params(model="doubao-seed-1.6")
    assert "thinking" in supported_params

    mapped_params = config.map_openai_params(
        non_default_params={
            "thinking": {"type": "disabled"},
        },
        optional_params={},
        model="doubao-seed-1.6",
        drop_params=False,
    )

    assert mapped_params == {
        "thinking": {"type": "disabled"},
    }

    e2e_mapped_params = get_optional_params(
        model="doubao-seed-1.6",
        custom_llm_provider="volcengine",
        thinking={"type": "enabled"},
        drop_params=False,
    )

    assert "thinking" in e2e_mapped_params and e2e_mapped_params["thinking"] == {
        "type": "enabled",
    }

def success_handler(  # noqa: PLR0915
    self, result=None, start_time=None, end_time=None, cache_hit=None, **kwargs
):
    verbose_logger.debug(
        f"Logging Details LiteLLM-Success Call: Cache_hit={cache_hit}"
    )
    if not self.should_run_logging(
        event_type="sync_success"
    ):  # prevent double logging
        return
    start_time, end_time, result = self._success_handler_helper_fn(
        start_time=start_time,
        end_time=end_time,
        result=result,
        cache_hit=cache_hit,
        standard_logging_object=kwargs.get("standard_logging_object", None),
    )
    try:
        ## BUILD COMPLETE STREAMED RESPONSE
        complete_streaming_response: Optional[
            Union[ModelResponse, TextCompletionResponse, ResponsesAPIResponse]
        ] = None
        if "complete_streaming_response" in self.model_call_details:
            return  # break out of this.
        complete_streaming_response = self._get_assembled_streaming_response(
            result=result,
            start_time=start_time,
            end_time=end_time,
            is_async=False,
            streaming_chunks=self.sync_streaming_chunks,
        )
        if complete_streaming_response is not None:
            verbose_logger.debug(
                "Logging Details LiteLLM-Success Call streaming complete"
            )
            self.model_call_details["complete_streaming_response"] = (
                complete_streaming_response
            )
            self.model_call_details["response_cost"] = (
                self._response_cost_calculator(result=complete_streaming_response)
            )
            ## STANDARDIZED LOGGING PAYLOAD
            self.model_call_details["standard_logging_object"] = (
                get_standard_logging_object_payload(
                    kwargs=self.model_call_details,
                    init_response_obj=complete_streaming_response,
                    start_time=start_time,
                    end_time=end_time,
                    logging_obj=self,
                    status="success",
                    standard_built_in_tools_params=self.standard_built_in_tools_params,
                )
            )
        callbacks = self.get_combined_callback_list(
            dynamic_success_callbacks=self.dynamic_success_callbacks,
            global_callbacks=litellm.success_callback,
        )

        ## REDACT MESSAGES ##
        result = redact_message_input_output_from_logging(
            model_call_details=(
                self.model_call_details
                if hasattr(self, "model_call_details")
                else {}
            ),
            result=result,
        )
        ## LOGGING HOOK ##
        for callback in callbacks:
            if isinstance(callback, CustomLogger):
                self.model_call_details, result = callback.logging_hook(
                    kwargs=self.model_call_details,
                    result=result,
                    call_type=self.call_type,
                )

        self.has_run_logging(event_type="sync_success")
        for callback in callbacks:
            try:
                litellm_params = self.model_call_details.get("litellm_params", {})
                should_run = self.should_run_callback(
                    callback=callback,
                    litellm_params=litellm_params,
                    event_hook="success_handler",
                )
                if not should_run:
                    continue
                if callback == "promptlayer" and promptLayerLogger is not None:
                    print_verbose("reaches promptlayer for logging!")
                    promptLayerLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "supabase" and supabaseClient is not None:
                    print_verbose("reaches supabase for logging!")
                    kwargs = self.model_call_details

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
                        else:
                            print_verbose("reaches supabase for streaming logging!")
                            result = kwargs["complete_streaming_response"]

                    model = kwargs["model"]
                    messages = kwargs["messages"]
                    optional_params = kwargs.get("optional_params", {})
                    litellm_params = kwargs.get("litellm_params", {})
                    supabaseClient.log_event(
                        model=model,
                        messages=messages,
                        end_user=optional_params.get("user", "default"),
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        litellm_call_id=litellm_params.get(
                            "litellm_call_id", str(uuid.uuid4())
                        ),
                        print_verbose=print_verbose,
                    )
                if callback == "wandb" and weightsBiasesLogger is not None:
                    print_verbose("reaches wandb for logging!")
                    weightsBiasesLogger.log_event(
                        kwargs=self.model_call_details,
                        response_obj=result,
                        start_time=start_time,
                        end_time=end_time,
                        print_verbose=print_verbose,
                    )
                if callback == "logfire" and logfireLogger is not None:
                    verbose_logger.debug("reaches logfire for success logging!")
                    kwargs = {}
                    for k, v in self.model_call_details.items():
                        if (
                            k != "original_response"
                        ):  # copy.deepcopy raises errors as this could be a coroutine
                            kwargs[k] = v

                    # this only logs streaming once, complete_streaming_response exists i.e when stream ends
                    if self.stream:
                        if "complete_streaming_response" not in kwargs:
                            continue
