    data: Optional[Union[dict, str]] = None,
    json: Optional[Union[dict, str]] = None,
    params: Optional[dict] = None,
    headers: Optional[dict] = None,
    stream: bool = False,
    timeout: Optional[Union[float, httpx.Timeout]] = None,
):
    try:
        if timeout is not None:
            req = self.client.build_request(
                "PUT", url, data=data, json=json, params=params, headers=headers, timeout=timeout  # type: ignore
            )
        else:
            req = self.client.build_request(
                "PUT", url, data=data, json=json, params=params, headers=headers  # type: ignore
            )
        response = self.client.send(req, stream=stream)
        return response
    except httpx.TimeoutException:
        raise litellm.Timeout(
            message=f"Connection timed out after {timeout} seconds.",
            model="default-model-name",
            llm_provider="litellm-httpx-handler",
        )
    except Exception as e:
        raise e

def showwarning(message, category, filename, lineno, file=None, line=None):
    traceback_info = f"{filename}:{lineno}: {category.__name__}: {message}\n"
    if file is not None:
        file.write(traceback_info)


warnings.showwarning = showwarning

async def proxy_shutdown_event():
    global prisma_client, master_key, user_custom_auth, user_custom_key_generate
    verbose_proxy_logger.info("Shutting down LiteLLM Proxy Server")
    if prisma_client:
        verbose_proxy_logger.debug("Disconnecting from Prisma")
        await prisma_client.disconnect()

    if litellm.cache is not None:
        await litellm.cache.disconnect()

    await jwt_handler.close()

    if db_writer_client is not None:
        await db_writer_client.close()

    # flush remaining langfuse logs
    if "langfuse" in litellm.success_callback:
        try:
            # flush langfuse logs on shutdow
            from litellm.utils import langFuseLogger

            if langFuseLogger is not None:
                langFuseLogger.Langfuse.flush()
        except Exception:
            # [DO NOT BLOCK shutdown events for this]
            pass

    ## RESET CUSTOM VARIABLES ##
    cleanup_router_config_variables()

