def __send_var_list_update(  # noqa C901
    self,
    modified_vars: t.List[str],
    front_var: t.Optional[str] = None,
):
    ws_dict = {}
    is_custom_page = _Hooks()._is_in_custom_page_context()
    values = {v: _getscopeattr_drill(self, v) for v in modified_vars if is_custom_page or _is_moduled_variable(v)}  # type: ignore[arg-type]
    if not values:
        return
    for k, v in values.items():
        if isinstance(v, (_TaipyData, _TaipyContentHtml)) and v.get_name() in modified_vars:
            modified_vars.remove(v.get_name())
        elif isinstance(v, _DoNotUpdate):
            modified_vars.remove(k)
    custom_page_filtered_types = _Hooks()._get_resource_handler_data_layer_supported_types()
    in_custom_page_context = _Hooks()._is_in_custom_page_context()
    for _var in modified_vars:
        if not self.__is_front_end_variable(_var) and not in_custom_page_context:
            _TaipyLogger._get_logger().debug(f"Skipping variable '{_var}' not in front-end.")
            continue
        newvalue = values.get(_var)
        if isinstance(newvalue, (_TaipyData)) or (
            custom_page_filtered_types and isinstance(newvalue, custom_page_filtered_types)
        ):  # type: ignore
            newvalue = {"__taipy_refresh": True}
        else:
            is_json = False
            if isinstance(newvalue, (_TaipyContent, _TaipyContentImage)):
                ret_value = self.__get_content_accessor().get_info(
                    t.cast(str, front_var), newvalue.get(), isinstance(newvalue, _TaipyContentImage)
                )
                if isinstance(ret_value, tuple):
                    newvalue = f"/{Gui._CONTENT_ROOT}/{ret_value[0]}"
                else:
                    newvalue = ret_value
            elif isinstance(newvalue, _TaipyContentHtml):
                newvalue = self._get_user_content_url(
                    None, {"variable_name": str(_var), Gui._HTML_CONTENT_KEY: str(time.time())}
                )
            elif isinstance(newvalue, (_TaipyLov, _TaipyLovValue)):
                newvalue = self.__adapter.run(
                    newvalue.get_name(), newvalue.get(), id_only=isinstance(newvalue, _TaipyLovValue)
                )
            elif isinstance(newvalue, _TaipyBase):
                is_json = isinstance(newvalue, _TaipyToJson)
                newvalue = newvalue.get()
            # Skip in taipy-gui, available in custom frontend
            if isinstance(newvalue, (dict, _MapDict)) and not in_custom_page_context:
                continue
            if isinstance(newvalue, float) and math.isnan(newvalue):
                # do not let NaN go through json, it is not handle well (dies silently through websocket)
                newvalue = None
            if newvalue is not None and not isinstance(newvalue, str) and not is_json:
                debug_warnings: t.List[warnings.WarningMessage] = []
                with warnings.catch_warnings(record=True) as warns:
                    warnings.resetwarnings()
                    json.dumps(newvalue, cls=_TaipyJsonEncoder)
                    if len(warns):
                        keep_value = True
                        for w in warns:
                            if is_debugging():
                                debug_warnings.append(w)
                            if w.category is not DeprecationWarning and w.category is not PendingDeprecationWarning:
                                keep_value = False
                                break
                        if not keep_value:
                            # do not send data that is not serializable
                            continue
                for w in debug_warnings:
                    warnings.warn(w.message, w.category)  # noqa: B028
        ws_dict[_var] = newvalue
    # TODO: What if value == newvalue?
    self.__send_ws_update_with_dict(ws_dict)

def __get_sequence_tasks(tasks: Union[List[Task], List[TaskId]]) -> List[Task]:
    task_manager = _TaskManagerFactory._build_manager()
    _tasks: List[Task] = []
    for task in tasks:
        if isinstance(task, Task):
            _tasks.append(task)
        elif _task := task_manager._get(task):
            _tasks.append(_task)
        else:
            raise NonExistingTask(task)
    return _tasks

def parse(self, o):
    if isinstance(o, Icon):
        return o._to_dict()
    if isinstance(o, _MapDict):
        return o._dict
    if isinstance(o, _TaipyBase):
        return o.get()
    if isinstance(o, (datetime, date, time)):
        return _date_to_string(o)
    if isinstance(o, Path):
        return str(o)
    if isinstance(o, (timedelta, pandas.Timedelta)):
        return str(o)
    if isinstance(o, numpy.generic):
        return getattr(o, "tolist", lambda: o)()
    if isinstance(o, _DoNotUpdate):
        return None

def parse(self, o):
    try:
        for adapter in reversed(self._adapters):
            if (output := adapter.parse(o)) is not None:
                return output
        raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable (value: {o}).")
    except Exception as e:
        _warn("Exception while resolving JSON", e)
        return None

class DataNodeFilterSchema(DataNodeConfigSchema):
    operators = fields.List(fields.Nested(OperatorSchema))
    join_operator = fields.String(default="AND")

    for package in packages:
        classes = package["classes"]["class"]
        if not isinstance(classes, list):
            classes = [classes]
        for cls in classes:
            files[cls["@filename"]] = float(cls["@line-rate"]) * 100
    qty = 0
    sum_coverage = 0
    for file in changed_files:
        if file in files:
            coverage = files[file]
            print(f"Coverage for {file}: {coverage:.2f}%")  # noqa: T201
            sum_coverage += coverage
            qty += 1
        else:
            print(f"No coverage data found for {file}")  # noqa: T201

    if qty:
        if sum_coverage / qty < threshold:
            print(f"Coverage for changed files is below {threshold}%: {sum_coverage/qty:.2f}%")  # noqa: T201
            sys.exit(1)
        print(f"Coverage for changed files: {sum_coverage/qty:.2f}%")  # noqa: T201
    else:
        print("No file detected to run coverage for.")  # noqa: T201


def get_changed_files(base_branch):
    """Get the list of changed Python files in the pull request."""
    try:
        result = subprocess.run(
            ["git", "diff", "--name-only", f"origin/{base_branch}", "--", "*.py"],
            capture_output=True,
            text=True,
            check=True,
        )
        changed_files = [
            file.replace("taipy/", "")
            for file in result.stdout.strip().splitlines()
            if not file.startswith(("tests/", "tools/"))
        ]

def __get_tasks(self, raise_not_existing: bool = True) -> Dict[str, Task]:
    from ..task._task_manager_factory import _TaskManagerFactory

    _tasks = {}
    task_manager = _TaskManagerFactory._build_manager()
    non_existing_tasks: List = []
    for task_or_id in self._tasks:
        t = task_manager._get(task_or_id, task_or_id)

        if not isinstance(t, Task):
            if raise_not_existing:
                raise NonExistingTask(task_or_id)
            non_existing_tasks.append(task_or_id)
            continue
        _tasks[t.config_id] = t
    for t_id in non_existing_tasks:
        self._tasks.discard(t_id)  # type: ignore[arg-type]
    return _tasks

