        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication in '{self.__frame.f_code.co_name}'", e)
    else:
        grouping_message.append(payload)

def _serve_extension(self, path: str) -> t.Any:
    parts = path.split("/")
    last_error = ""
    resource_name = None
    if len(parts) > 1:
        libs = Gui.__extensions.get(parts[0], [])
        for library in libs:
            try:
                resource_name = library.get_resource("/".join(parts[1:]))
                if resource_name:
                    return self._server.send_file(resource_name)
            except Exception as e:
                last_error = f"\n{e}"  # Check if the resource is served by another library with the same name
    _warn(f"Resource '{resource_name or path}' not accessible for library '{parts[0]}'{last_error}")
    return self._server.create_http_response("", 404)

def __pre_render_pages(self) -> None:
    """Pre-render all pages to have a proper initialization of all variables"""
    self.__set_client_id_in_context()
    scope_metadata = self._get_data_scope_metadata()
    if scope_metadata[_DataScopes._META_PRE_RENDER]:
        return
    for page in self._config.pages:
        if page is not None:
            with contextlib.suppress(Exception):
                if (
                    page._renderer is not None
                    and _Hooks()._get_custom_page_type()
                    and isinstance(page._renderer, _Hooks()._get_custom_page_type())  # type: ignore[arg-type]
                ):
                    _Hooks()._bind_custom_page_variables(self, page._renderer, self._get_client_id())
                else:
                    page.render(self, silent=True)  # type: ignore[arg-type]
    if additional_pages := _Hooks()._get_additional_pages():
        for page in additional_pages:
            if isinstance(page, Page):
                with contextlib.suppress(Exception):
                    if (
                        page._renderer is not None
                        and _Hooks()._get_custom_page_type()
                        and isinstance(page, _Hooks()._get_custom_page_type())  # type: ignore[arg-type]
                    ):
                        _Hooks()._bind_custom_page_variables(self, page, self._get_client_id())
                    else:
                        new_page = _Page()
                        new_page._renderer = page
                        new_page.render(self, silent=True)  # type: ignore[arg-type]

    scope_metadata[_DataScopes._META_PRE_RENDER] = True

    for file in changed_files:
        if file in files:
            coverage = files[file]
            print(f"Coverage for {file}: {coverage:.2f}%")  # noqa: T201
            sum_coverage += coverage
            qty += 1
        else:
            print(f"No coverage data found for {file}")  # noqa: T201

    if qty:
        if sum_coverage / qty < threshold:
            print(f"Coverage for changed files is below {threshold}%: {sum_coverage/qty:.2f}%")  # noqa: T201
            sys.exit(1)
        print(f"Coverage for changed files: {sum_coverage/qty:.2f}%")  # noqa: T201
    else:
        print("No file detected to run coverage for.")  # noqa: T201


def get_changed_files(base_branch):
    """Get the list of changed Python files in the pull request."""
    try:
        result = subprocess.run(
            ["git", "diff", "--name-only", f"origin/{base_branch}", "--", "*.py"],
            capture_output=True,
            text=True,
            check=True,
        )
        changed_files = [
            file.replace("taipy/", "")
            for file in result.stdout.strip().splitlines()
            if not file.startswith(("tests/", "tools/"))
        ]

def edit_entity(self, state: State, id: str, payload: t.Dict[str, str]):
    self.__lazy_start()
    args = payload.get("args")
    if args is None or not isinstance(args, list) or len(args) < 1 or not isinstance(args[0], dict):
        return
    error_var = payload.get("error_id")
    data = t.cast(dict, args[0])
    entity_id = t.cast(str, data.get(_GuiCoreContext.__PROP_ENTITY_ID))
    sequence = data.get("sequence")
    if not self.__check_readable_editable(state, entity_id, "Scenario", error_var):
        return
    scenario = t.cast(Scenario, core_get(entity_id))
    if scenario:
        try:
            if not sequence:
                if isinstance(sequence, str) and (name := data.get(_GuiCoreContext.__PROP_ENTITY_NAME)):
                    scenario.add_sequence(name, t.cast(list, data.get("task_ids")))
                else:
                    primary = data.get(_GuiCoreContext.__PROP_SCENARIO_PRIMARY)
                    if primary is True:
                        if not (reason := is_promotable(scenario)):
                            _GuiCoreContext.__assign_var(
                                state, error_var, f"Scenario {entity_id} is not promotable: {_get_reason(reason)}."
                            )
                            return
                        set_primary(scenario)
                    self.__edit_properties(scenario, data)
            else:
                if data.get("del", False):
                    scenario.remove_sequence(sequence)
                else:
                    name = t.cast(str, data.get(_GuiCoreContext.__PROP_ENTITY_NAME))
                    if sequence != name:
                        scenario.rename_sequence(sequence, name)
                    if seqEntity := scenario.sequences.get(name):
                        seqEntity.tasks = t.cast(list, data.get("task_ids"))
                        self.__edit_properties(seqEntity, data)
                    else:
                        _GuiCoreContext.__assign_var(
                            state,
                            error_var,
                            f"Sequence {name} is not available in Scenario {entity_id}.",
                        )
                        return

            _GuiCoreContext.__assign_var(state, error_var, "")
        except Exception as e:
            _GuiCoreContext.__assign_var(state, error_var, f"Error updating {type(scenario).__name__}. {e}")

def _auth_listener(self, state: State, client_id: t.Optional[str], payload: t.Dict[str, t.Any]):
    self.gui._broadcast( # type: ignore
        _GuiCoreContext._AUTH_CHANGED_NAME,
        payload.get("override", "")
        if (reason := can_create())
        else f"Cannot create scenario: {_get_reason(reason)}",
        client_id,
    )

def __get_sequence_tasks(tasks: Union[List[Task], List[TaskId]]) -> List[Task]:
    task_manager = _TaskManagerFactory._build_manager()
    _tasks: List[Task] = []
    for task in tasks:
        if isinstance(task, Task):
            _tasks.append(task)
        elif _task := task_manager._get(task):
            _tasks.append(_task)
        else:
            raise NonExistingTask(task)
    return _tasks

def __get_tasks(self, raise_not_existing: bool = True) -> Dict[str, Task]:
    from ..task._task_manager_factory import _TaskManagerFactory

    _tasks = {}
    task_manager = _TaskManagerFactory._build_manager()
    non_existing_tasks: List = []
    for task_or_id in self._tasks:
        t = task_manager._get(task_or_id, task_or_id)

        if not isinstance(t, Task):
            if raise_not_existing:
                raise NonExistingTask(task_or_id)
            non_existing_tasks.append(task_or_id)
            continue
        _tasks[t.config_id] = t
    for t_id in non_existing_tasks:
        self._tasks.discard(t_id)  # type: ignore[arg-type]
    return _tasks

def __check_sequence_tasks_exist_in_scenario_tasks(
    sequence_name: str, sequence_task_ids: Set[TaskId], scenario_id: ScenarioId, scenario_task_ids: Set[TaskId]
):
    non_existing_sequence_task_ids_in_scenario = set()
    for sequence_task_id in sequence_task_ids:
        if sequence_task_id not in scenario_task_ids:
            non_existing_sequence_task_ids_in_scenario.add(sequence_task_id)
    if len(non_existing_sequence_task_ids_in_scenario) > 0:
        raise SequenceTaskDoesNotExistInScenario(
            list(non_existing_sequence_task_ids_in_scenario), sequence_name, scenario_id
        )

def _set_sequence(
    self,
    name: str,
    tasks: Union[List[Task], List[TaskId]],
    properties: Optional[Dict] = None,
    subscribers: Optional[List[_Subscriber]] = None,
) -> Sequence:
    _scenario = _Reloader()._reload(self._MANAGER_NAME, self)
    _scenario_task_ids = {task.id if isinstance(task, Task) else task for task in _scenario._tasks}
    _sequence_task_ids: Set[TaskId] = {task.id if isinstance(task, Task) else task for task in tasks}
    self.__check_sequence_tasks_exist_in_scenario_tasks(name, _sequence_task_ids, self.id, _scenario_task_ids)

    from taipy.core.sequence._sequence_manager_factory import _SequenceManagerFactory

    seq_manager = _SequenceManagerFactory._build_manager()
    seq = seq_manager._create(name, tasks, subscribers or [], properties or {}, self.id, self.version)

    _sequences = _Reloader()._reload(self._MANAGER_NAME, self)._sequences
    _sequences.update(
        {
            name: {
                self._SEQUENCE_TASKS_KEY: tasks,
                self._SEQUENCE_PROPERTIES_KEY: properties or {},
                self._SEQUENCE_SUBSCRIBERS_KEY: subscribers or [],
            }
        }
    )
    self.sequences = _sequences  # type: ignore
    return seq

