		@self.registry.action(
			'Google Sheets: Update the content of a cell or range of cells', domains=['https://docs.google.com']
		)
		async def update_cell_contents(cell_or_range: str, new_contents_tsv: str, browser_session: BrowserSession):
			page = await browser_session.get_current_page()

			await select_cell_or_range(cell_or_range=cell_or_range, page=page)

			# simulate paste event from clipboard with TSV content
			await page.evaluate(f"""
				const clipboardData = new DataTransfer();
				clipboardData.setData('text/plain', `{new_contents_tsv}`);
				document.activeElement.dispatchEvent(new ClipboardEvent('paste', {{clipboardData}}));
			""")

			return ActionResult(
				extracted_content=f'Updated cells: {cell_or_range} = {new_contents_tsv}',
				include_in_memory=False,
				long_term_memory=f'Updated cells {cell_or_range} with {new_contents_tsv}',
			)

		@self.registry.action('Google Sheets: Clear whatever cells are currently selected', domains=['https://docs.google.com'])
		async def clear_cell_contents(cell_or_range: str, browser_session: BrowserSession):
			page = await browser_session.get_current_page()

			await select_cell_or_range(cell_or_range=cell_or_range, page=page)

			await page.keyboard.press('Backspace')
			return ActionResult(
				extracted_content=f'Cleared cells: {cell_or_range}',
				include_in_memory=False,
				long_term_memory=f'Cleared cells {cell_or_range}',
			)

		@self.registry.action('Google Sheets: Select a specific cell or range of cells', domains=['https://docs.google.com'])
		async def select_cell_or_range(cell_or_range: str, page: Page):
			await page.keyboard.press('Enter')  # make sure we dont delete current cell contents if we were last editing
			await page.keyboard.press('Escape')  # to clear current focus (otherwise select range popup is additive)
			await asyncio.sleep(0.1)
			await page.keyboard.press('Home')  # move cursor to the top left of the sheet first
			await page.keyboard.press('ArrowUp')
			await asyncio.sleep(0.1)
			await page.keyboard.press('Control+G')  # open the goto range popup
			await asyncio.sleep(0.2)
			await page.keyboard.type(cell_or_range, delay=0.05)
			await asyncio.sleep(0.2)
			await page.keyboard.press('Enter')
			await asyncio.sleep(0.2)
			await page.keyboard.press('Escape')  # to make sure the popup still closes in the case where the jump failed
			return ActionResult(
				extracted_content=f'Selected cells: {cell_or_range}',
				include_in_memory=False,
				long_term_memory=f'Selected cells {cell_or_range}',
			)

		@self.registry.action(
			'Google Sheets: Fallback method to type text into (only one) currently selected cell',
			domains=['https://docs.google.com'],
		)
		async def fallback_input_into_single_selected_cell(text: str, page: Page):
			await page.keyboard.type(text, delay=0.1)
			await page.keyboard.press('Enter')  # make sure to commit the input so it doesn't get overwritten by the next action
			await page.keyboard.press('ArrowUp')
			return ActionResult(
				extracted_content=f'Inputted text {text}',
				include_in_memory=False,
				long_term_memory=f"Inputted text '{text}' into cell",
			)

def _direct_capture(self, event: BaseTelemetryEvent) -> None:
	"""
	Should not be thread blocking because posthog magically handles it
	"""
	if self._posthog_client is None:
		return

	try:
		self._posthog_client.capture(
			self.user_id,
			event.name,
			{**event.properties, **POSTHOG_EVENT_SETTINGS},
		)
	except Exception as e:
		logger.error(f'Failed to send telemetry event {event.name}: {e}')

def are_images_identical(img_path1: str, img_path2: str) -> bool:
	"""Check if two images are identical by comparing their content."""
	try:
		with Image.open(img_path1) as img1, Image.open(img_path2) as img2:
			# Convert to same format for comparison
			if img1.mode != img2.mode:
				img1 = img1.convert('RGB')
				img2 = img2.convert('RGB')

			# Compare sizes first (quick check)
			if img1.size != img2.size:
				return False

			# Compare pixel data
			return list(img1.getdata()) == list(img2.getdata())
	except Exception as e:
		logger.warning(f'Failed to compare images {img_path1} and {img_path2}: {e}')
		return False

def _test_tool_calling_method(self, method: str) -> bool:
	"""Test if a specific tool calling method works with the current LLM."""
	try:
		# Test configuration
		CAPITAL_QUESTION = 'What is the capital of France? Respond with just the city name in lowercase.'
		EXPECTED_ANSWER = 'paris'

		class CapitalResponse(BaseModel):
			"""Response model for capital city question"""

			answer: str  # The name of the capital city in lowercase

		def is_valid_raw_response(response, expected_answer: str) -> bool:
			"""
			Cleans and validates a raw JSON response string against an expected answer.
			"""
			content = getattr(response, 'content', '').strip()
			# logger.debug(f'Raw response content: {content}')

			# Remove surrounding markdown code blocks if present
			if content.startswith('```json') and content.endswith('```'):
				content = content[7:-3].strip()
			elif content.startswith('```') and content.endswith('```'):
				content = content[3:-3].strip()

			# Attempt to parse and validate the answer
			try:
				result = json.loads(content)
				answer = str(result.get('answer', '')).strip().lower().strip(' .')

				if expected_answer.lower() not in answer:
					logger.debug(f"🛠️ Tool calling method {method} failed: expected '{expected_answer}', got '{answer}'")
					return False

				return True

			except (json.JSONDecodeError, AttributeError, TypeError) as e:
				logger.debug(f'🛠️ Tool calling method {method} failed: Failed to parse JSON content: {e}')
				return False

		if method == 'raw':
			# For raw mode, test JSON response format
			test_prompt = f"""{CAPITAL_QUESTION}
				Respond with a JSON object like: {{"answer": "city_name_in_lowercase"}}"""

			response = self.llm.invoke([test_prompt])
			# Basic validation of response
			if not response or not hasattr(response, 'content'):
				return False

			if not is_valid_raw_response(response, EXPECTED_ANSWER):
				return False
			return True
		else:
			# For other methods, try to use structured output
			structured_llm = self.llm.with_structured_output(CapitalResponse, include_raw=True, method=method)
			response = structured_llm.invoke([HumanMessage(content=CAPITAL_QUESTION)])

			if not response:
				logger.debug(f'🛠️ Tool calling method {method} failed: empty response')
				return False

			def extract_parsed(response: Any) -> CapitalResponse | None:
				if isinstance(response, dict):
					return response.get('parsed')
				return getattr(response, 'parsed', None)

			parsed = extract_parsed(response)

			if not isinstance(parsed, CapitalResponse):
				logger.debug(f'🛠️ Tool calling method {method} failed: LLM responded with invalid JSON')
				return False

			if EXPECTED_ANSWER not in parsed.answer.lower():
				logger.debug(f'🛠️ Tool calling method {method} failed: LLM failed to answer test question correctly')
				return False
			return True

	except Exception as e:
		logger.debug(f"🛠️ Tool calling method '{method}' test failed: {type(e).__name__}: {str(e)}")
		return False

async def ainvoke(
	self, messages: list[BaseMessage], output_format: type[T] | None = None
) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
	anthropic_messages, system_prompt = AnthropicMessageSerializer.serialize_messages(messages)

	try:
		if output_format is None:
			# Normal completion without structured output
			response = await self.get_client().messages.create(
				model=self.model,
				messages=anthropic_messages,
				system=system_prompt or NOT_GIVEN,
				**self._get_client_params_for_invoke(),
			)

			usage = self._get_usage(response)

			# Extract text from the first content block
			first_content = response.content[0]
			if isinstance(first_content, TextBlock):
				response_text = first_content.text
			else:
				# If it's not a text block, convert to string
				response_text = str(first_content)

			return ChatInvokeCompletion(
				completion=response_text,
				usage=usage,
			)

		else:
			# Use tool calling for structured output
			# Create a tool that represents the output format
			tool_name = output_format.__name__
			schema = SchemaOptimizer.create_optimized_json_schema(output_format)

			# Remove title from schema if present (Anthropic doesn't like it in parameters)
			if 'title' in schema:
				del schema['title']

			tool = ToolParam(
				name=tool_name,
				description=f'Extract information in the format of {tool_name}',
				input_schema=schema,
				cache_control=CacheControlEphemeralParam(type='ephemeral'),
			)

			# Force the model to use this tool
			tool_choice = ToolChoiceToolParam(type='tool', name=tool_name)

			response = await self.get_client().messages.create(
				model=self.model,
				messages=anthropic_messages,
				tools=[tool],
				system=system_prompt or NOT_GIVEN,
				tool_choice=tool_choice,
				**self._get_client_params_for_invoke(),
			)

			usage = self._get_usage(response)

			# Extract the tool use block
			for content_block in response.content:
				if hasattr(content_block, 'type') and content_block.type == 'tool_use':
					# Parse the tool input as the structured output
					try:
						return ChatInvokeCompletion(completion=output_format.model_validate(content_block.input), usage=usage)
					except Exception as e:
						# If validation fails, try to parse it as JSON first
						if isinstance(content_block.input, str):
							data = json.loads(content_block.input)
							return ChatInvokeCompletion(
								completion=output_format.model_validate(data),
								usage=usage,
							)
						raise e

			# If no tool use block found, raise an error
			raise ValueError('Expected tool use in response but none found')

	except APIConnectionError as e:
		raise ModelProviderError(message=e.message, model=self.name) from e
	except RateLimitError as e:
		raise ModelRateLimitError(message=e.message, model=self.name) from e
	except APIStatusError as e:
		raise ModelProviderError(message=e.message, status_code=e.status_code, model=self.name) from e
	except Exception as e:
		raise ModelProviderError(message=str(e), model=self.name) from e

async def ainvoke(
	self, messages: list[BaseMessage], output_format: type[T] | None = None
) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
	anthropic_messages, system_prompt = AnthropicMessageSerializer.serialize_messages(messages)

	try:
		if output_format is None:
			# Normal completion without structured output
			response = await self.get_client().messages.create(
				model=self.model,
				messages=anthropic_messages,
				system=system_prompt or NOT_GIVEN,
