	"""Prepare client parameters dictionary."""
	# Define base client params
	base_params = {
		'api_key': self.api_key,
		'auth_token': self.auth_token,
		'base_url': self.base_url,
		'timeout': self.timeout,
		'max_retries': self.max_retries,
