class HoneyPotBaseProtocol(insults.TerminalProtocol, TimeoutMixin):
    """
    Base protocol for interactive and non-interactive use
    """

    commands: ClassVar[dict] = {}
    for c in cowrie.commands.__all__:
        try:
            module = import_module(f"cowrie.commands.{c}")
            commands.update(module.commands)
        except ImportError as e:
            exc_type, exc_value, exc_traceback = sys.exc_info()
            log.err(
                "Failed to import command {}: {}: {}".format(
                    c,
                    e,
                    "".join(
                        traceback.format_exception(exc_type, exc_value, exc_traceback)
                    ),
                )
            )

def post_process_result(self, result: str) -> str:
    """Post-process the result to ensure it matches the expected format"""
    if not self._output_format:
        return result

    # Try to extract valid JSON if it's wrapped in code blocks or other text
    if self._output_format in ["json", "pydantic"]:
        try:
            # First, try to parse as is
            json.loads(result)
            return result
        except json.JSONDecodeError:
            # Try to extract JSON from the text
            import re

            json_match = re.search(r"(\{.*\})", result, re.DOTALL)
            if json_match:
                try:
                    extracted = json_match.group(1)
                    # Validate it's proper JSON
                    json.loads(extracted)
                    return extracted
                except:
                    pass

    return result

